<?php declare(strict_types=1); session_start(); require __DIR__.'/config.php'; if(empty($_SESSION['admin_logged'])){header('Location: admin.php');exit;} ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scanner | Rota da Prosperidade</title><link rel="stylesheet" href="assets/style.css"><script src="https://unpkg.com/html5-qrcode" defer></script></head><body class="system-page"><main class="scanner-shell"><header class="scanner-head"><div><span class="system-kicker">Controle de acesso</span><h1>Scanner de ingressos</h1><p>Aponte a câmera para o QR Code do participante.</p></div><a class="scanner-back" href="admin.php">← Voltar ao painel</a></header><div class="scanner-grid"><section class="scanner-card"><div id="reader"></div></section><section class="scanner-card"><div id="result" class="scan-result"><div><span class="result-icon">⌗</span><h2>Aguardando leitura</h2><p>O resultado da validação aparecerá aqui.</p></div></div></section></div></main><script>
window.addEventListener('DOMContentLoaded',()=>{let processing=false;const result=document.querySelector('#result');const show=(type,title,name='')=>{result.className='scan-result '+type;result.innerHTML=`<div><span class="result-icon">${type==='success'?'✓':type==='already'?'!':'×'}</span><h2>${title}</h2><p>${name}</p></div>`};const scanner=new Html5QrcodeScanner('reader',{fps:10,qrbox:{width:240,height:240}},false);scanner.render(text=>{if(processing)return;processing=true;fetch('api_checkin.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'hash='+encodeURIComponent(text)}).then(response=>response.json()).then(data=>{if(data.status==='success')show('success','Check-in liberado',data.nome);else if(data.status==='already')show('already','Entrada já registrada',data.nome);else show('invalid','Ingresso inválido ou inativo');setTimeout(()=>processing=false,2500)}).catch(()=>{show('invalid','Não foi possível validar');processing=false})})});
</script></body></html>
